"use client"

import { useMemo, useState } from "react"
import { Area, AreaChart, CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import { formatWan, formatCNY, formatPct, type YearPoint } from "@/lib/data"

type Mode = "value" | "profit"

const valueConfig = {
  total: { label: "总持仓", color: "var(--chart-1)" },
  principal: { label: "投入本金", color: "var(--chart-2)" },
} satisfies ChartConfig

const profitConfig = {
  profit: { label: "累计收益", color: "var(--chart-1)" },
} satisfies ChartConfig

export function PerformanceChart({
  series,
  title,
  subtitle,
}: {
  series: YearPoint[]
  title: string
  subtitle: string
}) {
  const [mode, setMode] = useState<Mode>("value")

  const last = series[series.length - 1]
  const totalProfit = last.total - last.principal
  const rate = last.principal === 0 ? 0 : totalProfit / last.principal
  const positive = totalProfit >= 0

  const profitData = useMemo(
    () => series.map((p) => ({ year: p.year, profit: p.total - p.principal })),
    [series],
  )

  return (
    <Card className="overflow-hidden">
      <CardHeader className="gap-6 sm:flex-row sm:items-start sm:justify-between">
        <div className="space-y-1">
          <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">
            {subtitle}
          </p>
          <h2 className="text-pretty text-xl font-semibold">{title}</h2>
        </div>

        <div className="flex items-end gap-8">
          <div className="space-y-1">
            <p className="text-xs text-muted-foreground">当前总持仓</p>
            <p className="font-mono text-2xl font-semibold tabular-nums">{formatCNY(last.total)}</p>
          </div>
          <div className="space-y-1">
            <p className="text-xs text-muted-foreground">累计收益</p>
            <p
              className="font-mono text-2xl font-semibold tabular-nums"
              style={{ color: positive ? "var(--gain)" : "var(--loss)" }}
            >
              {formatPct(rate)}
            </p>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="inline-flex rounded-full border border-border p-0.5 text-xs">
            <button
              type="button"
              onClick={() => setMode("value")}
              className={`rounded-full px-3 py-1 font-medium transition-colors ${
                mode === "value" ? "bg-foreground text-background" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              本金 vs 总持仓
            </button>
            <button
              type="button"
              onClick={() => setMode("profit")}
              className={`rounded-full px-3 py-1 font-medium transition-colors ${
                mode === "profit" ? "bg-foreground text-background" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              收益走势
            </button>
          </div>
          <p className="hidden text-xs text-muted-foreground sm:block">点击图表可切换视图</p>
        </div>

        <button
          type="button"
          aria-label="点击切换图表视图"
          onClick={() => setMode((m) => (m === "value" ? "profit" : "value"))}
          className="block w-full cursor-pointer text-left"
        >
          {mode === "value" ? (
            <ChartContainer config={valueConfig} className="h-[300px] w-full">
              <AreaChart data={series} margin={{ left: 4, right: 12, top: 8 }}>
                <defs>
                  <linearGradient id="fillTotal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="var(--color-total)" stopOpacity={0.25} />
                    <stop offset="100%" stopColor="var(--color-total)" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid vertical={false} strokeDasharray="3 3" />
                <XAxis dataKey="year" tickLine={false} axisLine={false} tickMargin={10} />
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  width={44}
                  tickFormatter={(v) => formatWan(v as number)}
                />
                <ChartTooltip
                  content={
                    <ChartTooltipContent
                      formatter={(value, name) => (
                        <div className="flex w-full items-center justify-between gap-4">
                          <span className="text-muted-foreground">
                            {name === "total" ? "总持仓" : "投入本金"}
                          </span>
                          <span className="font-mono font-medium tabular-nums">
                            {formatCNY(value as number)}
                          </span>
                        </div>
                      )}
                    />
                  }
                />
                <Area
                  dataKey="total"
                  type="monotone"
                  stroke="var(--color-total)"
                  strokeWidth={2.5}
                  fill="url(#fillTotal)"
                />
                <Area
                  dataKey="principal"
                  type="monotone"
                  stroke="var(--color-principal)"
                  strokeWidth={1.5}
                  strokeDasharray="4 4"
                  fill="none"
                />
              </AreaChart>
            </ChartContainer>
          ) : (
            <ChartContainer config={profitConfig} className="h-[300px] w-full">
              <LineChart data={profitData} margin={{ left: 4, right: 12, top: 8 }}>
                <CartesianGrid vertical={false} strokeDasharray="3 3" />
                <XAxis dataKey="year" tickLine={false} axisLine={false} tickMargin={10} />
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  width={44}
                  tickFormatter={(v) => formatWan(v as number)}
                />
                <ChartTooltip
                  content={
                    <ChartTooltipContent
                      formatter={(value) => (
                        <div className="flex w-full items-center justify-between gap-4">
                          <span className="text-muted-foreground">累计收益</span>
                          <span className="font-mono font-medium tabular-nums">
                            {formatCNY(value as number)}
                          </span>
                        </div>
                      )}
                    />
                  }
                />
                <Line
                  dataKey="profit"
                  type="monotone"
                  stroke="var(--color-profit)"
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                  activeDot={{ r: 5 }}
                />
              </LineChart>
            </ChartContainer>
          )}
        </button>
      </CardContent>
    </Card>
  )
}
