"use client"

import { Activity } from "lucide-react"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { formatCNY, type Fund } from "@/lib/data"

export function PlanTimeline({ fund }: { fund: Fund | null }) {
  return (
    <Card className="h-full">
      <CardHeader className="gap-1">
        <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">时间轴</p>
        <h2 className="text-lg font-semibold">定投调整历程</h2>
      </CardHeader>
      <CardContent>
        {!fund ? (
          <div className="flex h-[280px] flex-col items-center justify-center gap-3 text-center">
            <div className="flex size-12 items-center justify-center rounded-full bg-muted">
              <Activity className="size-5 text-muted-foreground" />
            </div>
            <p className="max-w-[16rem] text-pretty text-sm text-muted-foreground">
              从左侧选择一个基金，查看它每一次定投计划的调整时间线
            </p>
          </div>
        ) : (
          <ol className="relative ml-1 border-l border-border pl-6">
            {fund.adjustments.map((adj, i) => {
              const stopped = adj.monthlyAmount === null
              return (
                <li key={adj.id} className={i === fund.adjustments.length - 1 ? "" : "pb-6"}>
                  <span
                    className="absolute -left-[6.5px] mt-1 size-3 rounded-full border-2 border-background"
                    style={{ backgroundColor: stopped ? "var(--loss)" : "var(--brand)" }}
                    aria-hidden
                  />
                  <p className="font-mono text-xs text-muted-foreground">{adj.date}</p>
                  <p className="mt-1 text-sm font-medium">{adj.action}</p>
                  <p className="mt-1 text-sm leading-relaxed text-muted-foreground">{adj.reason}</p>
                  <div className="mt-2">
                    {stopped ? (
                      <Badge variant="secondary">停止定投</Badge>
                    ) : (
                      <Badge variant="outline" className="font-mono font-normal">
                        月投 {formatCNY(adj.monthlyAmount as number)}
                      </Badge>
                    )}
                  </div>
                </li>
              )
            })}
          </ol>
        )}
      </CardContent>
    </Card>
  )
}
