export type AssetCategory = "fund" | "stock" | "bond" | "cash"

export const categoryLabels: Record<AssetCategory, string> = {
  fund: "基金",
  stock: "股票",
  bond: "债券",
  cash: "现金",
}

export type YearPoint = {
  year: number
  /** 累计投入本金 */
  principal: number
  /** 当前总市值 */
  total: number
}

export type PlanAdjustment = {
  id: string
  date: string
  /** 更改原因 */
  reason: string
  /** 调整动作简述 */
  action: string
  /** 调整后的月定投金额，null 表示停止定投 */
  monthlyAmount: number | null
  note?: string
}

export type Fund = {
  id: string
  name: string
  code: string
  category: AssetCategory
  /** 定投是否进行中 */
  active: boolean
  /** 当前月定投金额 */
  monthlyAmount: number
  startDate: string
  /** 累计投入本金 */
  principal: number
  /** 当前市值 */
  current: number
  series: YearPoint[]
  adjustments: PlanAdjustment[]
}

export function returnRate(f: { principal: number; current: number }) {
  return (f.current - f.principal) / f.principal
}

export function profit(f: { principal: number; current: number }) {
  return f.current - f.principal
}

