"use client"

import { Card, CardContent, CardHeader } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { leaderboard, formatPct, returnRate, categoryLabels } from "@/lib/data"

export function Leaderboard({
  onSelect,
}: {
  onSelect?: (id: string, active: boolean) => void
}) {
  const max = Math.max(...leaderboard.map((f) => Math.abs(returnRate(f))))

  return (
    <Card className="h-full">
      <CardHeader className="gap-1">
        <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">收益排行榜</p>
        <h2 className="text-lg font-semibold">按收益率排序</h2>
      </CardHeader>
      <CardContent className="space-y-1">
        {leaderboard.map((f, i) => {
          const rate = returnRate(f)
          const positive = rate >= 0
          const width = (Math.abs(rate) / max) * 100
          return (
            <button
              type="button"
              key={f.id}
              onClick={() => onSelect?.(f.id, f.active)}
              className="flex w-full items-center gap-4 rounded-xl px-3 py-2.5 text-left transition-colors hover:bg-muted/60"
            >
              <span className="w-5 shrink-0 font-mono text-sm tabular-nums text-muted-foreground">
                {i + 1}
              </span>
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <p className="truncate text-sm font-medium">{f.name}</p>
                  {!f.active && (
                    <Badge variant="secondary" className="shrink-0 font-normal text-muted-foreground">
                      归档
                    </Badge>
                  )}
                </div>
                <div className="mt-1.5 h-1.5 w-full overflow-hidden rounded-full bg-muted">
                  <span
                    className="block h-full rounded-full"
                    style={{ width: `${width}%`, backgroundColor: positive ? "var(--gain)" : "var(--loss)" }}
                  />
                </div>
              </div>
              <span
                className="w-16 shrink-0 text-right font-mono text-sm font-semibold tabular-nums"
                style={{ color: positive ? "var(--gain)" : "var(--loss)" }}
              >
                {formatPct(rate)}
              </span>
            </button>
          )
        })}
      </CardContent>
    </Card>
  )
}
