"use client"

import { useMemo, useState } from "react"
import { PerformanceChart } from "@/components/performance-chart"
import { PlanPanel } from "@/components/plan-panel"
import { PlanTimeline } from "@/components/plan-timeline"
import { AssetOverview } from "@/components/asset-overview"
import { Leaderboard } from "@/components/leaderboard"
import { ThemeToggle } from "@/components/theme-toggle"
import { Button } from "@/components/ui/button"
import { funds, portfolioSeries } from "@/lib/data"

export function Dashboard() {
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [tab, setTab] = useState<"active" | "archived">("active")
  const [view, setView] = useState<"list" | "detail">("list")

  const selectedFund = useMemo(
    () => funds.find((f) => f.id === selectedId) ?? null,
    [selectedId],
  )

  const chartSeries = selectedFund ? selectedFund.series : portfolioSeries
  const chartTitle = selectedFund ? selectedFund.name : "投资组合总览"
  const chartSubtitle = selectedFund ? `${selectedFund.code} · 本金与市值走势` : "全部进行中持仓 · 本金与市值走势"

  function handleSelect(id: string) {
    setSelectedId((prev) => (prev === id ? null : id))
    setView("list")
  }

  function handleLeaderboardSelect(id: string, active: boolean) {
    setTab(active ? "active" : "archived")
    setSelectedId(id)
    setView("list")
  }

  return (
    <div className="mx-auto max-w-[1400px] px-5 py-8 sm:px-8 lg:px-12">
      <header className="mb-10 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="flex size-9 items-center justify-center rounded-xl bg-brand text-brand-foreground">
            <span className="font-mono text-base font-bold">盈</span>
          </div>
          <div>
            <h1 className="text-lg font-semibold leading-none">盈析</h1>
            <p className="mt-1 text-xs text-muted-foreground">理财数据分析看板</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {selectedFund && (
            <Button variant="ghost" size="sm" onClick={() => setSelectedId(null)}>
              返回组合总览
            </Button>
          )}
          <ThemeToggle />
        </div>
      </header>

      <div className="space-y-6">
        <PerformanceChart series={chartSeries} title={chartTitle} subtitle={chartSubtitle} />

        <div className="grid gap-6 lg:grid-cols-2">
          <PlanPanel
            tab={tab}
            onTabChange={(t) => {
              setTab(t)
              setSelectedId(null)
              setView("list")
            }}
            selectedId={selectedId}
            onSelect={handleSelect}
            view={view}
            onViewChange={setView}
          />
          <PlanTimeline fund={selectedFund} />
        </div>

        <div className="grid gap-6 lg:grid-cols-2">
          <AssetOverview />
          <Leaderboard onSelect={handleLeaderboardSelect} />
        </div>
      </div>

      <footer className="mt-12 border-t border-border pt-6 text-center text-xs text-muted-foreground">
        数据仅用于展示与分析，不构成任何投资建议
      </footer>
    </div>
  )
}
