"use client"

import { ArrowLeft, ArrowRight, ChevronRight } from "lucide-react"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import {
  activeFunds,
  archivedFunds,
  categoryLabels,
  formatCNY,
  formatPct,
  returnRate,
  type Fund,
} from "@/lib/data"

function RateBadge({ fund }: { fund: Fund }) {
  const rate = returnRate(fund)
  const positive = rate >= 0
  return (
    <span
      className="font-mono text-sm font-semibold tabular-nums"
      style={{ color: positive ? "var(--gain)" : "var(--loss)" }}
    >
      {formatPct(rate)}
    </span>
  )
}

function PlanRow({
  fund,
  selected,
  onSelect,
}: {
  fund: Fund
  selected: boolean
  onSelect: () => void
}) {
  return (
    <button
      type="button"
      onClick={onSelect}
      className={`flex w-full items-center gap-4 rounded-xl border px-4 py-3.5 text-left transition-colors ${
        selected
          ? "border-brand/60 bg-brand/5"
          : "border-transparent hover:bg-muted/60"
      }`}
    >
      <span
        className="h-9 w-1 shrink-0 rounded-full"
        style={{ backgroundColor: selected ? "var(--brand)" : "var(--border)" }}
        aria-hidden
      />
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <p className="truncate text-sm font-medium">{fund.name}</p>
          <Badge variant="secondary" className="shrink-0 font-normal text-muted-foreground">
            {categoryLabels[fund.category]}
          </Badge>
        </div>
        <p className="mt-0.5 font-mono text-xs text-muted-foreground">
          {fund.code}
          {fund.active ? ` · 月投 ${formatCNY(fund.monthlyAmount)}` : " · 已停止"}
        </p>
      </div>
      <div className="text-right">
        <RateBadge fund={fund} />
        <p className="mt-0.5 text-xs text-muted-foreground">收益率</p>
      </div>
      <ChevronRight
        className={`size-4 shrink-0 transition-colors ${selected ? "text-brand" : "text-muted-foreground/40"}`}
      />
    </button>
  )
}

export function PlanPanel({
  tab,
  onTabChange,
  selectedId,
  onSelect,
  view,
  onViewChange,
}: {
  tab: "active" | "archived"
  onTabChange: (t: "active" | "archived") => void
  selectedId: string | null
  onSelect: (id: string) => void
  view: "list" | "detail"
  onViewChange: (v: "list" | "detail") => void
}) {
  const list = tab === "active" ? activeFunds : archivedFunds
  const selected = list.find((f) => f.id === selectedId) ?? null

  if (view === "detail" && selected) {
    return <PlanDetail fund={selected} onBack={() => onViewChange("list")} />
  }

  return (
    <Card className="h-full">
      <CardHeader className="gap-4">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">
              定投计划
            </p>
            <h2 className="text-lg font-semibold">
              {tab === "active" ? "进行中的计划" : "已归档计划"}
            </h2>
          </div>
          <div className="inline-flex rounded-full border border-border p-0.5 text-xs">
            {(["active", "archived"] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => onTabChange(t)}
                className={`rounded-full px-3 py-1 font-medium transition-colors ${
                  tab === t ? "bg-foreground text-background" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                {t === "active" ? "进行中" : "归档"}
              </button>
            ))}
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-1.5">
        {list.map((fund) => (
          <PlanRow
            key={fund.id}
            fund={fund}
            selected={fund.id === selectedId}
            onSelect={() => onSelect(fund.id)}
          />
        ))}

        {selected && (
          <div className="pt-2">
            <Button className="w-full" onClick={() => onViewChange("detail")}>
              查看「{selected.name}」定投详情
              <ArrowRight className="size-4" />
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

function PlanDetail({ fund, onBack }: { fund: Fund; onBack: () => void }) {
  return (
    <Card className="h-full">
      <CardHeader className="gap-4">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex w-fit items-center gap-1.5 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground"
        >
          <ArrowLeft className="size-3.5" />
          返回计划列表
        </button>
        <div className="space-y-1">
          <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">
            定投详情
          </p>
          <h2 className="text-pretty text-lg font-semibold">{fund.name}</h2>
        </div>
        <div className="grid grid-cols-3 gap-3">
          <Metric label="投入本金" value={formatCNY(fund.principal)} />
          <Metric label="当前市值" value={formatCNY(fund.current)} />
          <Metric
            label="收益率"
            value={formatPct(returnRate(fund))}
            color={returnRate(fund) >= 0 ? "var(--gain)" : "var(--loss)"}
          />
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <Separator />
        <div>
          <p className="mb-3 text-sm font-medium">定投调整记录</p>
          <div className="space-y-2.5">
            {[...fund.adjustments].reverse().map((adj) => (
              <div key={adj.id} className="rounded-xl border border-border/70 p-3.5">
                <div className="flex items-center justify-between gap-3">
                  <span className="text-sm font-medium">{adj.action}</span>
                  <span className="font-mono text-xs text-muted-foreground">{adj.date}</span>
                </div>
                <p className="mt-1.5 text-sm text-muted-foreground">{adj.reason}</p>
                <div className="mt-2.5 flex items-center gap-2 text-xs">
                  <span className="text-muted-foreground">调整后：</span>
                  {adj.monthlyAmount === null ? (
                    <Badge variant="secondary">停止定投</Badge>
                  ) : (
                    <span className="font-mono font-medium">月投 {formatCNY(adj.monthlyAmount)}</span>
                  )}
                </div>
                {adj.note && <p className="mt-2 text-xs text-muted-foreground/80">备注：{adj.note}</p>}
              </div>
            ))}
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

function Metric({ label, value, color }: { label: string; value: string; color?: string }) {
  return (
    <div className="rounded-lg bg-muted/50 p-3">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className="mt-1 font-mono text-sm font-semibold tabular-nums" style={color ? { color } : undefined}>
        {value}
      </p>
    </div>
  )
}
