"use client"

import { useMemo } from "react"
import { Label, Pie, PieChart } from "recharts"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from "@/components/ui/chart"
import { allocation, formatCNY, formatWan, totalAssets } from "@/lib/data"

const palette: Record<string, string> = {
  fund: "var(--chart-1)",
  stock: "var(--chart-3)",
  bond: "var(--chart-4)",
  cash: "var(--chart-5)",
}

const chartConfig: ChartConfig = {
  value: { label: "市值" },
  fund: { label: "基金", color: "var(--chart-1)" },
  stock: { label: "股票", color: "var(--chart-3)" },
  bond: { label: "债券", color: "var(--chart-4)" },
  cash: { label: "现金", color: "var(--chart-5)" },
}

export function AssetOverview() {
  const data = useMemo(
    () => allocation.map((a) => ({ ...a, fill: palette[a.category] })),
    [],
  )

  return (
    <Card className="h-full">
      <CardHeader className="gap-1">
        <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">资产总览</p>
        <h2 className="text-lg font-semibold">配置结构</h2>
      </CardHeader>
      <CardContent className="grid gap-6 sm:grid-cols-2 sm:items-center">
        <ChartContainer config={chartConfig} className="mx-auto aspect-square w-full max-w-[220px]">
          <PieChart>
            <ChartTooltip
              content={
                <ChartTooltipContent
                  hideLabel
                  formatter={(value, name) => (
                    <div className="flex w-full items-center justify-between gap-4">
                      <span className="text-muted-foreground">{chartConfig[name as string]?.label ?? name}</span>
                      <span className="font-mono font-medium tabular-nums">{formatCNY(value as number)}</span>
                    </div>
                  )}
                />
              }
            />
            <Pie data={data} dataKey="value" nameKey="category" innerRadius={62} outerRadius={92} strokeWidth={3} paddingAngle={2}>
              <Label
                content={({ viewBox }) => {
                  if (viewBox && "cx" in viewBox && "cy" in viewBox) {
                    return (
                      <text x={viewBox.cx} y={viewBox.cy} textAnchor="middle" dominantBaseline="middle">
                        <tspan x={viewBox.cx} y={viewBox.cy} className="fill-foreground font-mono text-2xl font-semibold">
                          {formatWan(totalAssets)}
                        </tspan>
                        <tspan x={viewBox.cx} y={(viewBox.cy ?? 0) + 22} className="fill-muted-foreground text-xs">
                          总资产
                        </tspan>
                      </text>
                    )
                  }
                }}
              />
            </Pie>
          </PieChart>
        </ChartContainer>

        <ul className="space-y-3">
          {data.map((a) => {
            const pct = (a.value / totalAssets) * 100
            return (
              <li key={a.category} className="flex items-center gap-3">
                <span className="size-2.5 shrink-0 rounded-full" style={{ backgroundColor: a.fill }} aria-hidden />
                <span className="flex-1 text-sm">{a.label}</span>
                <span className="font-mono text-sm tabular-nums text-muted-foreground">{pct.toFixed(1)}%</span>
                <span className="w-20 text-right font-mono text-sm tabular-nums">{formatWan(a.value)}</span>
              </li>
            )
          })}
        </ul>
      </CardContent>
    </Card>
  )
}
